import{_ as t,o as l,c as n,j as e,a as r}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第99章 那棵树还在","description":"","frontmatter":{},"headers":[],"relativePath":"第99章_那棵树还在.md","filePath":"第99章_那棵树还在.md"}'),o={name:"第99章_那棵树还在.md"};function s(_,a,p,c,d,i){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"第99章-那棵树还在",tabindex:"-1"},[r("第99章 那棵树还在 "),e("a",{class:"header-anchor",href:"#第99章-那棵树还在","aria-label":'Permalink to "第99章 那棵树还在"'},"​")],-1),e("p",null,"那天下午我在机场里还剩两个半钟头。我出去了。我不是去她那个城市里逛，我是去了那条街。这件事我要从头讲。那天十点二十，我坐在那个 B 口，我忽然想起一个东西。我想起她那年三月跟我讲的那句话。她说，奶茶店旁边那棵树，你每年三月去站一下，看它还在不在。",-1),e("p",null,"那天是十二月二十五号。我提前了两个月，跟她那年一样，也是不按她定的日子。我算过那个机场离那条街多远。我算得出来，因为我三年前坐过一班公交，从那头数第三个门。机场到那条街，公交四十分钟。我还有两个半小时。我去取了行李。对，我那天有托运。那个托运是一个袋子。我妈在袋子里塞了两件换洗衣服，她说你在外面万一回不来。我拿那个袋子下楼，走到机场外面那个公交站。我等车等了十四分钟。车上人不多。我坐靠窗，我从头数那个街。我不确定是哪一站。我到第四站下来，因为那一站有一个超市，超市门口挂着一排拖鞋。我下车以后往回走。我走了大概六分钟。我看见了那家奶茶店。招牌还是那个方的，白底红字。我走到那棵树底下。",-1),e("p",null,'那棵树还在。歪得很厉害，往街心倒。树底下那堆煤渣没了，换成了一个垃圾桶。树上那道刻痕还在。我凑过去看。那道沟比三年之前更深了一点，木头从边上翻起来，白的一圈。我站在那里看那个字。三年之前我看不出是什么字。三年以后我还是看不出。但是我这次注意到一件事。那道刻痕下面，有人拿粉笔补过一次。粉笔早被雨冲没了，只剩一点白色的印子，在木头的沟里。我那时候不知道是不是她补的。我站在那里想了一个可能：是她。她哪一年补的，她补的时候几岁，她在不在那条街上被人看见过。我算不出来。那条街这三年变了很多。银行变成了一个卖药的，卷帘门上喷了一个很大的"药"字。超市还在，但是门口那一排拖鞋换成了一排塑料凳。超市里多了一个收快递的点，门口堆了十几个箱子。我那天在那个收快递的点前面站了很久。因为那个柜台上贴着一张纸，纸上写着：取件请报手机后四位。三年前我在我们那个驿站里，每天报的是我自己的后四位。我那天身上带了一个东西。一个很小的塑封袋，里面装了两枚徽章。那是她去年冬天丢了的一对小卡里的两枚，她以为被别人拿了。我在她那一堆仓库里翻到的，在两张色纸中间。我一直没跟她讲。我那天拿着那个袋子，站在那棵树下。我想我可以放在这个树底下那个垃圾桶边上。我想我可以塞在那个收快递的点里，写上她家那个门牌。我两样都没做。我把那个袋子放回背包。因为我忽然想到一件事。我今天要是把它放在这里，她哪天拿到，她就要问一句：这个东西在你那里多久了。她一算这个"多久"，她就要算三年。她算三年，她今天这一天就过不好。所以我那天把这两枚徽章带回来了。我把它们放进了仓库最里面那一个盒子里。我在盒子上写了两个字：不数。',-1),e("p",null,"我在那个树底下站的时候，有一件事发生。有一个扫地的老人从我旁边过。她拿那个扫帚把树下那堆叶子拢到一起去。拢到一半她抬头看我。她说，你找谁。我说，不找。她说，你在这个树底下站了得五分钟。我说，我等人。她说，这里没有人。她说，这句话她讲得很自然。她说，这里没有人，因为这些年轻人都不在这儿了。她说，她说这个口以前下午很多人，现在只剩一个奶茶店。她说，那个奶茶店以前那个招牌是圆的。我说，我知道。她说，你知道？我说，我以前来过。她说，以前这里小孩多。她说，有一个小女孩天天从这个树底下跑过去。她说，她跑的时候一只手拿着一个本子。我站在那里，手里那个扫帚的声音停了。我说，她穿什么。她说，校服。她说，蓝色的那种，很宽。她说，她现在不在了。我说，她去哪儿了。她说，她姐接她走了。我说，她姐？她说，她姐在这条街上读高中，读了三年，天天在那个银行门口等。她说，那个银行还没变成药铺的时候就有了。她说，那个小姑娘天天在那儿站着，背一个很旧的包。她说，我那时候扫地，我看她站得久，我有一次问她，她说她在背书。她说，她说她在背英语。她说，背完她就要走回去，因为家里没人做饭。我站在那里。我没说话。那个扫地的人把扫帚拿起来，她往前面走了。她走了两步回头。她说，你找谁。我说，我找人。她说，这里没有人。我那天回机场晚了。路上修路，那个车绕了一段，我到那个站是十一点五十四。我还有六分钟过那个安检。",-1),e("p",null,'我把那个小本子塞到背包里，开始跑。我跑了大概三百米。我跑到那个门口的时候，喘得说不出一句话。我拿身份证，我把那个袋子抬上去。前面那个人回头看了我一眼。他说，赶得上。我说，谢谢。他说，你跑成这样你肯定是赶着去见一个人。我说，不是。他说，不是你会跑成这样。我过那个安检的时候，手里那个小本子差一点掉在地上。我把本子接住了。接住那一下，我心里想的不是那棵树。我想的是那个背英语的人。我在机场那个 B 口坐下来，我把那个小本子拿出来。我在那行"十二月二十五，树在"的下面，又加了一行。我写：这里有人记得你站过。树底下那个垃圾桶上贴着一张纸。纸上是那种很旧的、社区写的提示："请勿在此倾倒。"那张纸的一角被人撕掉了。我从口袋里拿出口袋里那个小本子。我在那个本子上画了那棵树。我画得比三年前好了一点。我画完了那个树，我在下面写了一行。我写：十二月二十五，树在。我那时候算过时间。回去要四十分钟公交，加上走路。我还有二十五分钟。我往回走到那个车站。我等车又等了十二分钟。我上车以后坐靠窗，我把那个小本子放在膝盖上。',-1),e("p",null,'我那天在车上想：我要不要告诉她。我要是告诉她，我今天这一趟就不是我一个人的。我要是不告诉她，我今天这一趟跟三年前那一趟，就全是我的。而全是我的，它就是一件没有人知道的事。一件没有人知道的事，是不能变成账的。她说过："我不要拿你那个本子当账。"我要是不讲，我就没有拿它当账。我要是讲了，她今天就要想她该怎么回。她该怎么回这件事，她今天早上在医院那条走廊上已经算过了。我那天到了机场是十一点五十四。我还有六分钟过那个安检。我坐下，把手机拿出来。我发的是：我今天中午吃了一个面包。她说：你吃那个面包干什么，你不是有人送吗。我说：那个咖啡我喝完了，面包我留着中午吃。她说：你留面包干什么。我说：我怕我下午饿。她说：你这个人真的。她说：你什么都不敢浪费。我说，我浪费不起。她说，你今天不许讲这种话。我说，为什么。她说，因为今天你讲了，我今天在我妈床边睡不着。我说，那我不讲。她说，你今天在哪儿。我说，我在 B 口。她说，你今天没有出去吧。我看着这一句。我坐在那个塑料椅子上，手里还捏着那个小本子。我说，没有。她说，好。她说，我今天不问你。她说，我今天问你我怕你说谎，你说谎我听出来我更难受。她说，所以我不问。',-1),e("p",null,"那天我上的飞机是十二点二十。我在飞机上把那个小本子塞到书包最里面那一格。那一格里已经有一张纸。那张纸是我那年一月在她家铁门把手上挂过的那一种，同一批。我没有第二张挂上去。我留着它是因为我怕有一天我要再挂一次。我到现在没挂。",-1)])])}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
